   763  /* Reads a value from an ASN1 tree, then interprets it as the provided
   764   * type of string and returns the output in an allocated variable.
   765   *
   766   * Note that this function always places a null character
   767   * at the end of a readable string value (which is not accounted into size)
   768   */
   769  int
   770  _gnutls_x509_read_string(ASN1_TYPE c, const char *root,
   771                           gnutls_datum_t * ret, unsigned int etype, unsigned int allow_ber)
   772  {
   773          int len = 0, result;
   774          size_t slen;
   775          uint8_t *tmp = NULL;
   776          unsigned rtype;
   777
   778          result = asn1_read_value_type(c, root, NULL, &len, &rtype);
   779          if (result != ASN1_MEM_ERROR) {
   780                  gnutls_assert();
   781                  result = _gnutls_asn2err(result);
   782                  return result;
   783          }
   784
   785          if (rtype == ASN1_ETYPE_BIT_STRING)
   786                  len /= 8;
   787
   788          tmp = gnutls_malloc((size_t) len + 1);
   789          if (tmp == NULL) {
   790                  gnutls_assert();
   791                  result = GNUTLS_E_MEMORY_ERROR;
   792                  goto cleanup;
   793          }
   794
   795          result = asn1_read_value(c, root, tmp, &len);
   796          if (result != ASN1_SUCCESS) {
   797                  gnutls_assert();
   798                  result = _gnutls_asn2err(result);
   799                  goto cleanup;
   800          }
   801
   802          if (rtype == ASN1_ETYPE_BIT_STRING)
   803                  len /= 8;
   804
   805          /* Extract the STRING.
   806           */
   807          slen = (size_t) len;
   808
   809          result = _gnutls_x509_decode_string(etype, tmp, slen, ret, allow_ber);
   810          if (result < 0) {
   811                  gnutls_assert();
   812                  goto cleanup;
   813          }
   814          gnutls_free(tmp);
   815
   816          return 0;
   817
   818        cleanup:
   819          gnutls_free(tmp);
   820          return result;
   821  }
